window.I18N = (function () {
  const dict = window.TRANSLATIONS;
  const DEFAULT = "en";
  let saved = null;
  try { saved = localStorage.getItem("lang"); } catch (e) {}
  let lang = saved === "ru" ? "ru" : DEFAULT;

  // String by key (for JS code).
  function t(key) {
    const d = dict[lang] || {};
    return d[key] !== undefined ? d[key] : (dict.en[key] !== undefined ? dict.en[key] : key);
  }
  // Value from data: {en: "...", ru: "..."} or a plain string.
  function L(v) {
    if (v && typeof v === "object") return v[lang] !== undefined ? v[lang] : v.en;
    return v;
  }
  function locale() { return lang === "ru" ? "ru-RU" : "en-US"; }

  function applyAttr(attr) {
    document.querySelectorAll("[data-i18n-" + attr + "]").forEach((el) => {
      const key = el.getAttribute("data-i18n-" + attr);
      const orig = "data-i18n-" + attr + "-en";
      if (!el.hasAttribute(orig)) el.setAttribute(orig, el.getAttribute(attr) || "");
      if (lang === "en") el.setAttribute(attr, el.getAttribute(orig));
      else if (dict.ru[key] !== undefined) el.setAttribute(attr, dict.ru[key]);
    });
  }

  function apply() {
    document.documentElement.lang = lang;
    document.querySelectorAll("[data-i18n]").forEach((el) => {
      const key = el.dataset.i18n;
      if (el.dataset.i18nEn === undefined) el.dataset.i18nEn = el.innerHTML;
      if (lang === "en") el.innerHTML = el.dataset.i18nEn;
      else if (dict.ru[key] !== undefined) el.innerHTML = dict.ru[key];
    });
    ["placeholder", "content", "aria-label"].forEach(applyAttr);
    document.querySelectorAll(".lang button").forEach((b) => b.classList.toggle("active", b.dataset.lang === lang));
  }

  function set(next) {
    if (next !== "ru" && next !== "en") return;
    lang = next;
    try { localStorage.setItem("lang", lang); } catch (e) {}
    apply();
    document.dispatchEvent(new CustomEvent("langchange", { detail: { lang } }));
  }

  document.querySelectorAll(".lang button").forEach((b) => b.addEventListener("click", () => set(b.dataset.lang)));
  apply();

  return { get lang() { return lang; }, t, L, locale, set };
})();
